"""Helper for SSH connections modeled after telnetlib where feasible/needed.
There are -however- several deviations from telnetlib on read-methods and how
errors are handled.
"""
__all__ = ["SSH", "SFTP"]
from System import UnauthorizedAccessException
from System.IO import File, IOException
from System.Net.Sockets import SocketException
from System.Threading import Thread

try:
    from IVTools.CommonModules.SSHModule import ShellConnection
except ImportError:
    import clr

    clr.AddReference("SSHModule")
    from IVTools.CommonModules.SSHModule import ShellConnection
try:
    from Renci.SshNet import SftpClient
    from Renci.SshNet.Common import SshException
except ImportError:
    import clr

    clr.AddReference("Renci.SshNet")
    from Renci.SshNet import SftpClient
    from Renci.SshNet.Common import SshException

SSH_PORT = 22


def _sleep(seconds):
    Thread.Sleep(seconds * 1000)


class SSH(object):
    """Class to help with SSH connections to controlled devices. Partially
    modeled after telnetlib.
    """

    # pylint: disable=R0913
    def __init__(self, host=None, port=SSH_PORT, username='', password='', timeout=60, lte_oms=None, log_file=None):
        """Constructor.

        Named parameters:
        host      -- IP address of the SSH server.
        port      -- SSH port. Default is 22.
        username  -- User name to shell.
        password  -- Password for user.
        timeout   -- Timeout for connection.
        lte_oms   -- LteOmsControl can be used instead of other data here.
        log_file  -- Path to file where traffic will be logged. None if no logging is necessary (default).
        """
        self.host = host
        self.port = port
        self.timeout = timeout
        self.username = username
        self.password = password
        self.lte_oms = lte_oms
        self.log_file_name = log_file
        self.log_file = None
        self.stop_ssh_log = False

    # pylint: enable=R0913

    def __incoming_data(self, data, offset, length):
        sdata = ''.join(chr(x) for x in data[offset:(offset + length)])
        if self.log_file:
            try:
                self.log_file.write(sdata)
            except IOError:
                print("%s: writing to log file failed." % (__file__))
        if len(self.buff) > 10485760:  # if buffer is over 10 MB, clear buffer.
            self.buff = ''
        self.buff += sdata

    # pylint: disable=R0913
    def open(self, host=None, port=None, username=None, password=None, timeout=None):
        """Opens connetion to SSH server.

        Named parameters:
        host      -- IP address of the SSH server.
        port      -- SSH port.
        username  -- User name to shell.
        password  -- Password for user.
        timeout   -- Timeout for connection.

        Returns:
        True on successful connection.
        """
        self.connection = None
        if self.lte_oms:
            self.connection = self.lte_oms.CreateShellConnection()
        else:
            host = host or self.host
            port = port or self.port
            timeout = timeout or self.timeout
            username = username or self.username
            password = password or self.password
            self.connection = ShellConnection(host, port, username, password, False)
        self.connection.LogLevel = 0x00
        connected = self.connection.Connect(self.timeout or -1)
        _sleep(1)
        if self.log_file_name:
            try:
                self.log_file = open(self.log_file_name, 'wb+', 1)
            except IOError as e:
                print("%s: unable to open '%s': %s" % (__file__, self.log_file_name, str(e)))
        self.connection.SubscribeToRawDataMessages(self.__incoming_data)
        self.buff = ''
        return connected

    # pylint: enable=R0913

    def close(self):
        """Closes existing connection to server.
        """
        if self.connection:
            self.connection.UnsubscribeFromRawDataMessages(self.__incoming_data)
            self.connection.Disconnect()
            self.connection = None
        if self.log_file:
            self.log_file.close()
            self.log_file = None
            self.buff = ''

    def write(self, buff):
        """Writes text to connection.

        Named parameters:
        buff -- Text that should be written.

        Return value:
        True on successful send.
        """
        self.buff = ''
        return self.connection.Send(buff)

    def read_until(self, expected, timeout=600):
        """Reads from connection until given text is received or timeout has
        occured.

        Named parameters:
        expected -- Value that is waited from connection.
        timeout  -- Timeout to wait for expected value (in seconds). Defaults 
                    to 600.

        Return value:
        Received text up to expected value -or- empty string if timeout occurs.
        """
        for _ in range(timeout):
            i = self.buff.find(expected)
            if i >= 0:
                ret = self.buff[:(i + len(expected))]
                self.buff = self.buff[(i + len(expected)):]
                return ret
            else:
                _sleep(1)
        return ''

    def read_forever(self):
        while True:
            print(self.buff[:])

    def start_log_over_ssh(self):
        prev = 0
        while not self.stop_ssh_log:
            if len(self.buff) > prev:
                prev = len(self.buff)
        return ''

    def stop_log_over_ssh(self):
        self.stop_ssh_log = True

    def read_return_of_command(self, command):
        return self.connection.SendAndRecordOutput(command)

    def expect(self, lst, timeout=600):
        """Reads from connection until any of the given regexes matches
        received or timeout has occured.

        Named parameters:
        lst     -- List of regexes (can be either string or instance of re
                   object) that are waited from connection.
        timeout -- Timeout to wait for expected values (in seconds). Defaults 
                   to 600.

        Return value:
        Received text up to expected value -or- empty string if timeout occurs.
        """
        re = None
        n = len(lst)
        for i in range(n):
            if not hasattr(lst[i], "search"):
                if not re:
                    import re
                lst[i] = re.compile(lst[i])
        for _ in range(timeout):
            for i in range(n):
                m = lst[i].search(self.buff)
                if m:
                    e = m.end()
                    ret = self.buff[:e]
                    self.buff = self.buff[e:]
                    return ret
            _sleep(1)
        return ''

    def __enter__(self):
        if self.open():
            return self
        return None

    def __exit__(self, exc_type, exc_value, exc_traceback):
        self.close()
        if exc_type:
            return False
        return True


class SFTP(object):
    """Class that helps with SFTP trasfers."""

    # pylint: disable=R0913
    def __init__(self, host=None, port=SSH_PORT, username='', password='', timeout=60):
        """Constructor.

        Named parameters:
        host      -- IP address of the SSH server.
        port      -- SSH port. Default is 22.
        username  -- User name to shell.
        password  -- Password for user.
        timeout   -- Timeout for connection.
        """
        self.host = host
        self.port = port
        self.timeout = timeout
        self.username = username
        self.password = password

    # pylint: enable=R0913

    # pylint: disable=R0913
    def open(self, host=None, port=None, username=None, password=None, timeout=None):
        """Opens connetion to SFTP server.

        Named parameters:
        host      -- IP address of the SFTP server.
        port      -- SFTP port.
        username  -- User name to shell.
        password  -- Password for user.
        timeout   -- Timeout for connection.

        Returns:
        True on successful connection.
        """
        self.connection = None
        host = host or self.host
        port = port or self.port
        timeout = timeout or self.timeout
        username = username or self.username
        password = password or self.password
        self.connection = SftpClient(host, port, username, password)
        try:
            self.connection.Connect()
            connected = self.connection.IsConnected
            if not connected:
                self.close()
        except (SocketException, SshException):
            connected = False
        _sleep(1)
        return connected

    # pylint: enable=R0913

    def close(self):
        """Closes existing connection to server.
        """
        if self.connection:
            try:
                self.connection.Disconnect()
            except SshException:
                pass
            self.connection = None

    def download_file(self, remote_file, local_file):
        """Download file from server to local computer.

        Named parameters:
        remote_file -- File name on server.
        local_file  -- File name in local computer."""
        if File.Exists(local_file):
            try:
                File.Delete(local_file)
            except (IOException, UnauthorizedAccessException):
                return False

        try:
            if self.connection:
                stream = File.OpenWrite(local_file)
                self.connection.DownloadFile(remote_file, stream)
                stream.Close()
        except (SshException, IOException):
            return False
        return True

    def upload_file(self, local_file, remote_file):
        """Upload file from local computer to server.

        Named parameters:
        local_file  -- File name in local computer.
        remote_file -- File name on server."""
        try:
            if self.connection:
                stream = File.OpenRead(local_file)
                self.connection.UploadFile(stream, remote_file)
                stream.Close()
        except SshException:
            return False
        except IOException:
            return False
        return True

    def __enter__(self):
        if self.open():
            return self
        return None

    def __exit__(self, exc_type, exc_value, exc_traceback):
        self.close()
        if exc_type:
            return False
        return True
